const body = $('Post-Call Webhook').first().json.body;
const call = body.call || body;

// Core identifiers
const callId = call.call_id || '';
const agentId = call.agent_id || '';

// Caller info
const fromNumber = call.from_number || '';
const toNumber = call.to_number || '';
const direction = call.direction || 'inbound';

// Timing
const startTime = call.start_timestamp ? new Date(call.start_timestamp).toISOString() : new Date().toISOString();
const endTime = call.end_timestamp ? new Date(call.end_timestamp).toISOString() : new Date().toISOString();
const durationSeconds = call.duration_ms ? Math.round(call.duration_ms / 1000) : 0;

// Status
const status = call.call_status || call.status || '';
const disconnectionReason = call.disconnection_reason || '';

// Transcript — join array or use raw string
let transcript = '';
if (call.transcript) {
  if (typeof call.transcript === 'string') {
    transcript = call.transcript;
  } else if (Array.isArray(call.transcript)) {
    transcript = call.transcript.map(t => `${t.role}: ${t.content}`).join('\n');
  }
}

// Call analysis (populated on call_analyzed event)
const analysis = call.call_analysis || {};
const summary = (analysis.custom_analysis_data && analysis.custom_analysis_data.localized_summary) || analysis.call_summary || analysis.summary || '';
const sentiment = analysis.user_sentiment || analysis.sentiment || '';
const successful = analysis.call_successful !== undefined ? analysis.call_successful : null;

return [{
  json: {
    callId,
    agentId,
    startTime,
    endTime,
    fromNumber,
    toNumber,
    direction,
    durationSeconds,
    status,
    disconnectionReason,
    transcript: transcript.substring(0, 50000),
    summary,
    sentiment,
    successful
  }
}];
